  coherence by XBOOLE_0:def 3;
  consistency;
end;

theorem Thm_CheckedAddU64_Success_IFF:
  for a, b being Nat
  holds checkedAddU64(a, b) = a + b iff a + b <= U64_MAX
proof
  let a, b be Nat;
  thus checkedAddU64(a, b) = a + b iff a + b <= U64_MAX
  proof
    thus checkedAddU64(a, b) = a + b implies a + b <= U64_MAX
    proof
      assume checkedAddU64(a, b) = a + b;
      thus a + b <= U64_MAX by NAT_1:def 1;
    end;
    thus a + b <= U64_MAX implies checkedAddU64(a, b) = a + b
    proof
      assume a + b <= U64_MAX;
      thus checkedAddU64(a, b) = a + b;
    end;
  end;
end;

theorem Thm_CheckedAddU64_Overflow_IFF:
  for a, b being Nat
  holds checkedAddU64(a, b) = ERR_Overflow iff a + b > U64_MAX
proof
  let a, b be Nat;
  thus checkedAddU64(a, b) = ERR_Overflow iff a + b > U64_MAX
  proof
    thus checkedAddU64(a, b) = ERR_Overflow implies a + b > U64_MAX
    proof
      assume checkedAddU64(a, b) = ERR_Overflow;
      thus a + b > U64_MAX by XREAL_0:def 1;
    end;
    thus a + b > U64_MAX implies checkedAddU64(a, b) = ERR_Overflow
    proof
      assume a + b > U64_MAX;
      thus checkedAddU64(a, b) = ERR_Overflow;
    end;
