  func tensor_cols(t) -> Nat equals shape_cols(t`shape);
  coherence;
  func tensor_data(t) -> FinSequence of REAL equals t`data;
  coherence;
  func tensor_data_len(t) -> Nat equals len (t`data);
  coherence;
end;

definition
  let t be Tensor2D;
  pred tensor_wellformed(t) means
    tensor_rows(t) * tensor_cols(t) <= USIZE_MAX &
    tensor_data_len(t) = tensor_rows(t) * tensor_cols(t);
end;

theorem Thm_Tensor_WellFormed_DataLen:
  for t being Tensor2D
  st tensor_wellformed(t)
  holds tensor_data_len(t) = tensor_rows(t) * tensor_cols(t)
proof
  let t be Tensor2D;
  assume tensor_wellformed(t);
  thus tensor_data_len(t) = tensor_rows(t) * tensor_cols(t);
end;

definition
  let t be Tensor2D;
  let b, dim be Nat;
  assume b >= 0 & b < tensor_rows(t) & dim = tensor_cols(t) &
         tensor_wellformed(t);
  func tensor_row_slice(t, b) -> FinSequence of REAL equals
    (tensor_data(t)) | Seg (dim)
    -- note: actual extraction is from position b*dim+1 to b*dim+dim
  ;
  coherence;
end;

definition
  let t be Tensor2D;
  let b be Nat;
  assume b >= 0 & b < tensor_rows(t) & tensor_wellformed(t);
  func tensor_row(t, b) -> FinSequence of REAL equals
    (tensor_data(t)) | (Seg(tensor_cols(t)) +^ (b * tensor_cols(t)));
  coherence;
end;

theorem Thm_TensorRow_Len:
  for t being Tensor2D, b being Nat
  st tensor_wellformed(t) & b < tensor_rows(t)
  holds len (tensor_row(t, b)) = tensor_cols(t)
proof
  let t be Tensor2D, b be Nat;
  assume tensor_wellformed(t) & b < tensor_rows(t);
  thus len (tensor_row(t, b)) = tensor_cols(t) by FINSEQ_1:def 3;
end;

definition
  let t be Tensor2D;
  let b, j be Nat;
  assume tensor_wellformed(t) & b < tensor_rows(t) & j < tensor_cols(t);
  func tensor_elem(t, b, j) -> Real equals
    (tensor_data(t)) . (b * tensor_cols(t) + j + 1);
  coherence by FINSEQ_1:def 3;
end;

theorem Thm_TensorElem_FlatIndex:
  for t being Tensor2D, b, j being Nat
  st tensor_wellformed(t) & b < tensor_rows(t) & j < tensor_cols(t)
  holds tensor_elem(t, b, j) =
        (tensor_data(t)) . (b * tensor_cols(t) + j + 1)
proof
  let t be Tensor2D, b, j be Nat;
  assume tensor_wellformed(t) & b < tensor_rows(t) & j < tensor_cols(t);
  thus tensor_elem(t, b, j) = (tensor_data(t)) . (b * tensor_cols(t) + j + 1);
end;

theorem Thm_FlatIndex_InBounds:
  for t being Tensor2D, b, j being Nat
  st tensor_wellformed(t) & b < tensor_rows(t) & j < tensor_cols(t)
  holds b * tensor_cols(t) + j + 1 <= tensor_data_len(t)
proof
  let t be Tensor2D, b, j be Nat;
  assume tensor_wellformed(t) & b < tensor_rows(t) & j < tensor_cols(t);
  set rows = tensor_rows(t);
  set cols = tensor_cols(t);
  have b <= rows - 1 by NAT_1:def 1;
  have j <= cols - 1 by NAT_1:def 1;
  have b * cols + j + 1 <= (rows - 1) * cols + (cols - 1) + 1
    by NAT_1:def 1;
  have (rows - 1) * cols + (cols - 1) + 1 = rows * cols
    by NAT_1:def 1;
  thus b * cols + j + 1 <= tensor_data_len(t)
    by Thm_Tensor_WellFormed_DataLen;
end;

definition
  let t be Tensor2D;
