    sa`byte_len > 0 & sb`byte_len > 0 &
    sa`base_addr < sb`base_addr + sb`byte_len &
    sb`base_addr < sa`base_addr + sa`byte_len;
end;

theorem Thm_StoragesOverlap_Sym:
  for sa, sb being TensorStorage
  st storages_overlap(sa, sb) holds storages_overlap(sb, sa)
proof
