theorem Thm_CheckedMul_Zero_Left:
  for b being Nat holds checkedMul_Nat(0, b) = 0
proof
  let b be Nat;
  have 0 * b = 0 by XCMPLX_0:def 7;
  have 0 <= USIZE_MAX by NAT_1:def 1;
  thus checkedMul_Nat(0, b) = 0 by Thm_CheckedMul_Success_Preserves_Value;
end;

theorem Thm_CheckedMul_Zero_Right:
  for a being Nat holds checkedMul_Nat(a, 0) = 0
proof
  let a be Nat;
  have a * 0 = 0 by XCMPLX_0:def 7;
  have 0 <= USIZE_MAX by NAT_1:def 1;
  thus checkedMul_Nat(a, 0) = 0 by Thm_CheckedMul_Success_Preserves_Value;
end;

theorem Thm_CheckedMul_One_Left:
  for b being Nat st b <= USIZE_MAX
  holds checkedMul_Nat(1, b) = b
proof
  let b be Nat;
  assume b <= USIZE_MAX;
  have 1 * b = b by XCMPLX_0:def 7;
  thus checkedMul_Nat(1, b) = b by Thm_CheckedMul_Success_Preserves_Value;
end;

theorem Thm_CheckedAdd_Zero_Left:
  for b being Nat st b <= USIZE_MAX
  holds checkedAdd_Nat(0, b) = b
proof
  let b be Nat;
  assume b <= USIZE_MAX;
  have 0 + b = b by XCMPLX_0:def 4;
  thus checkedAdd_Nat(0, b) = b by Thm_CheckedAdd_Success_Preserves_Value;
end;

theorem Thm_CheckedMul_Commutative_Success:
  for a, b being Nat st a * b <= USIZE_MAX
  holds checkedMul_Nat(a, b) = checkedMul_Nat(b, a)
proof
  let a, b be Nat;
  assume a * b <= USIZE_MAX;
  have a * b = b * a by XCMPLX_0:def 7;
  thus checkedMul_Nat(a, b) = a * b by Thm_CheckedMul_Success_Preserves_Value;
  have b * a = a * b by XCMPLX_0:def 7;
  have b * a <= USIZE_MAX by XREAL_0:def 1;
  have checkedMul_Nat(b, a) = b * a
    by Thm_CheckedMul_Success_Preserves_Value;
  thus checkedMul_Nat(a, b) = checkedMul_Nat(b, a) by XCMPLX_0:def 7;
end;

