definition
  let x, lo, hi be Real;
  func clip(x, lo, hi) -> Real equals
    lo if x < lo
    else hi if x > hi
    else x;
  coherence;
  consistency;
end;

theorem Thm_Clip_BelowMin:
  for x, lo, hi be Real st x < lo
  holds clip(x, lo, hi) = lo
proof
  let x, lo, hi be Real;
  assume x < lo;
  thus clip(x, lo, hi) = lo;
end;

theorem Thm_Clip_AboveMax:
  for x, lo, hi be Real st x > hi
  holds clip(x, lo, hi) = hi
proof
  let x, lo, hi be Real;
  assume x > hi;
  thus clip(x, lo, hi) = hi;
end;

theorem Thm_Clip_InRange:
  for x, lo, hi be Real st x >= lo & x <= hi
  holds clip(x, lo, hi) = x
proof
  let x, lo, hi be Real;
  assume x >= lo & x <= hi;
  thus clip(x, lo, hi) = x;
end;

theorem Thm_Clip_In_Bounds:
  for x, lo, hi be Real
  st lo <= hi
  holds clip(x, lo, hi) >= lo & clip(x, lo, hi) <= hi
proof
  let x, lo, hi be Real;
  assume lo <= hi;
  per cases;
  suppose x < lo;
    thus clip(x, lo, hi) = lo by Thm_Clip_BelowMin;
    thus clip(x, lo, hi) >= lo & clip(x, lo, hi) <= hi by XREAL_0:def 1;
  suppose x > hi;
    thus clip(x, lo, hi) = hi by Thm_Clip_AboveMax;
    thus clip(x, lo, hi) >= lo & clip(x, lo, hi) <= hi by XREAL_0:def 1;
  suppose x >= lo & x <= hi;
    thus clip(x, lo, hi) = x by Thm_Clip_InRange;
    thus clip(x, lo, hi) >= lo & clip(x, lo, hi) <= hi;
  end;
end;

theorem Thm_Clip_Idempotent:
  for x, lo, hi be Real st lo <= hi
  holds clip(clip(x, lo, hi), lo, hi) = clip(x, lo, hi)
proof
  let x, lo, hi be Real;
  assume lo <= hi;
  set c = clip(x, lo, hi);
  have c >= lo & c <= hi by Thm_Clip_In_Bounds;
  thus clip(c, lo, hi) = c by Thm_Clip_InRange;
end;

definition
  let x be Real;
  func rsf_exp(x) -> Real equals exp_R(x);
  coherence;
end;

theorem Thm_Exp_Positive:
  for x be Real holds rsf_exp(x) > 0
proof
  let x be Real;
  thus rsf_exp(x) > 0 by TAYLOR_1:def 1;
end;

theorem Thm_Exp_Zero:
  rsf_exp(0) = 1
proof
  thus rsf_exp(0) = 1 by TAYLOR_1:def 1;
end;

theorem Thm_Exp_Sum:
  for a, b be Real holds rsf_exp(a + b) = rsf_exp(a) * rsf_exp(b)
proof
  let a, b be Real;
  thus rsf_exp(a + b) = rsf_exp(a) * rsf_exp(b) by TAYLOR_1:def 1;
end;

theorem Thm_Exp_Neg:
  for x be Real holds rsf_exp(-x) = 1 / rsf_exp(x)
proof
  let x be Real;
  have rsf_exp(x) > 0 by Thm_Exp_Positive;
  thus rsf_exp(-x) = 1 / rsf_exp(x) by TAYLOR_1:def 1;
end;

theorem Thm_Exp_Div:
  for a, b be Real holds rsf_exp(a) / rsf_exp(b) = rsf_exp(a - b)
proof
  let a, b be Real;
  have rsf_exp(-b) = 1 / rsf_exp(b) by Thm_Exp_Neg;
  have rsf_exp(a) * rsf_exp(-b) = rsf_exp(a - b) by Thm_Exp_Sum;
  thus rsf_exp(a) / rsf_exp(b) = rsf_exp(a - b) by XCMPLX_0:def 9;
end;

