:: tolerance comparison: |av - bv| <= abs_tol + rel_tol * max(|av|, |bv|)
definition
  let av, bv, abs_tol, rel_tol be Real;
  pred allclose_elem(av, bv, abs_tol, rel_tol) means
    av is_finite & bv is_finite &
    |. av - bv .| <= abs_tol + rel_tol * (max(|. av .|, |. bv .|));
end;

theorem Thm_AllClose_Refl:
  for v, abs_tol, rel_tol be Real
  st v is_finite & abs_tol >= 0 & rel_tol >= 0
  holds allclose_elem(v, v, abs_tol, rel_tol)
proof
  let v, abs_tol, rel_tol be Real;
  assume v is_finite & abs_tol >= 0 & rel_tol >= 0;
  have |. v - v .| = |. 0 .| by XCMPLX_0:def 5;
  have |. 0 .| = 0 by COMPLEX1:def 1;
  have abs_tol + rel_tol * (max(|. v .|, |. v .|)) >= 0 by XREAL_0:def 1;
  thus allclose_elem(v, v, abs_tol, rel_tol);
end;

theorem Thm_AllClose_Sym:
  for av, bv, abs_tol, rel_tol be Real
  st allclose_elem(av, bv, abs_tol, rel_tol)
  holds allclose_elem(bv, av, abs_tol, rel_tol)
proof
  let av, bv, abs_tol, rel_tol be Real;
  assume allclose_elem(av, bv, abs_tol, rel_tol);
  have |. bv - av .| = |. -(av - bv) .| by XCMPLX_0:def 5;
  have |. -(av - bv) .| = |. av - bv .| by COMPLEX1:def 1;
  have max(|. bv .|, |. av .|) = max(|. av .|, |. bv .|) by XXREAL_0:def 9;
  thus allclose_elem(bv, av, abs_tol, rel_tol);
end;

theorem Thm_AllClose_ZeroTol_IFF_Equal:
  for av, bv be Real
  st av is_finite & bv is_finite
  holds allclose_elem(av, bv, 0, 0) iff av = bv
proof
  let av, bv be Real;
  assume av is_finite & bv is_finite;
  thus allclose_elem(av, bv, 0, 0) iff av = bv
  proof
    thus allclose_elem(av, bv, 0, 0) implies av = bv
    proof
      assume allclose_elem(av, bv, 0, 0);
      have |. av - bv .| <= 0 by XREAL_0:def 1;
      have |. av - bv .| >= 0 by COMPLEX1:def 1;
      have |. av - bv .| = 0 by XREAL_0:def 1;
      thus av = bv by COMPLEX1:def 1;
    end;
    thus av = bv implies allclose_elem(av, bv, 0, 0)
    proof
      assume av = bv;
      thus allclose_elem(av, bv, 0, 0) by Thm_AllClose_Refl;
    end;
  end;
end;

definition
  let a, b be Tensor2D;
  let abs_tol, rel_tol be Real;
  pred tensorAllCloseEq_val(a, b, abs_tol, rel_tol) means
    valid_tolerances(abs_tol, rel_tol) &
    validateTensor2D_ok(a) & validateTensor2D_ok(b) &
    tensorsSameShape(a, b) &
    for i being Nat st 1 <= i & i <= tensor_data_len(a)
    holds allclose_elem(
      (tensor_data(a)) . i,
      (tensor_data(b)) . i,
      abs_tol, rel_tol);
