theorem Thm_TensorAllCloseEq_Refl:
  for t being Tensor2D, abs_tol, rel_tol be Real
  st valid_tolerances(abs_tol, rel_tol) &
     validateTensor2D_ok(t) &
     ensureFiniteSlice_ok(tensor_data(t))
  holds tensorAllCloseEq_val(t, t, abs_tol, rel_tol)
proof
  let t be Tensor2D, abs_tol, rel_tol be Real;
  assume valid_tolerances(abs_tol, rel_tol) &
         validateTensor2D_ok(t) &
         ensureFiniteSlice_ok(tensor_data(t));
  have tensorsSameShape(t, t) by Thm_TensorsSameShape_Refl;
  thus tensorAllCloseEq_val(t, t, abs_tol, rel_tol)
  proof
    thus valid_tolerances(abs_tol, rel_tol);
    thus validateTensor2D_ok(t);
    thus validateTensor2D_ok(t);
    thus tensorsSameShape(t, t) by Thm_TensorsSameShape_Refl;
    let i be Nat;
    assume 1 <= i & i <= tensor_data_len(t);
    have (tensor_data(t)) . i is_finite
      by ensureFiniteSlice_ok(tensor_data(t));
    thus allclose_elem(
      (tensor_data(t)) . i,
      (tensor_data(t)) . i,
      abs_tol, rel_tol)
      by Thm_AllClose_Refl;
  end;
end;

theorem Thm_TensorAllCloseEq_Sym:
  for a, b being Tensor2D, abs_tol, rel_tol be Real
  st tensorAllCloseEq_val(a, b, abs_tol, rel_tol)
  holds tensorAllCloseEq_val(b, a, abs_tol, rel_tol)
proof
  let a, b be Tensor2D, abs_tol, rel_tol be Real;
  assume tensorAllCloseEq_val(a, b, abs_tol, rel_tol);
  have tensorsSameShape(b, a)
    by Thm_TensorsSameShape_Sym;
  thus tensorAllCloseEq_val(b, a, abs_tol, rel_tol)
  proof
    thus valid_tolerances(abs_tol, rel_tol)
      by tensorAllCloseEq_val(a, b, abs_tol, rel_tol);
    thus validateTensor2D_ok(b)
      by tensorAllCloseEq_val(a, b, abs_tol, rel_tol);
    thus validateTensor2D_ok(a)
      by tensorAllCloseEq_val(a, b, abs_tol, rel_tol);
    thus tensorsSameShape(b, a) by Thm_TensorsSameShape_Sym;
    let i be Nat;
    assume 1 <= i & i <= tensor_data_len(b);
    have allclose_elem(
      (tensor_data(a)) . i,
      (tensor_data(b)) . i,
      abs_tol, rel_tol)
      by tensorAllCloseEq_val(a, b, abs_tol, rel_tol);
    thus allclose_elem(
      (tensor_data(b)) . i,
      (tensor_data(a)) . i,
      abs_tol, rel_tol)
      by Thm_AllClose_Sym;
  end;
end;

theorem Thm_TensorAllCloseEq_InvalidTol_Fails:
  for a, b being Tensor2D, abs_tol, rel_tol be Real
