    validateTensor2D_ok(s_w) &
    tensor_rows(t_w) = dim & tensor_cols(t_w) = dim &
    validateTensor2D_ok(t_w) &
    tensor_rows(s_b) = 1 & tensor_cols(s_b) = dim &
    validateTensor2D_ok(s_b) &
    (for j being Nat st 1 <= j & j <= dim holds
      (tensor_data(s_b)) . j = 0) &
    tensor_rows(t_b) = 1 & tensor_cols(t_b) = dim &
    validateTensor2D_ok(t_b) &
    (for j being Nat st 1 <= j & j <= dim holds
      (tensor_data(t_b)) . j = 0) &
    (for i being Nat st 1 <= i & i <= dim * dim holds
      (tensor_data(s_w)) . i >= -xavier_bound(dim) &
      (tensor_data(s_w)) . i <= xavier_bound(dim)) &
    (for i being Nat st 1 <= i & i <= dim * dim holds
      (tensor_data(t_w)) . i >= -xavier_bound(dim) &
      (tensor_data(t_w)) . i <= xavier_bound(dim));
end;

